import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import API from '../api';

const emptyForm = {
  title: '', title_am: '', title_or: '',
  content: '', content_am: '', content_or: '',
  category: 'General', is_published: 1,
};

export default function NewsForm() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const navigate = useNavigate();

  const [form, setForm] = useState(emptyForm);
  const [images, setImages] = useState([]);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const [imgDesc, setImgDesc] = useState('');

  useEffect(() => {
    if (isEdit) {
      API.get(`/news/${id}`).then(({ data }) => {
        setForm({
          title: data.title || '', title_am: data.title_am || '', title_or: data.title_or || '',
          content: data.content || '', content_am: data.content_am || '', content_or: data.content_or || '',
          category: data.category || 'General', is_published: data.is_published ?? 1,
        });
        setImages(data.images || []);
      });
    }
  }, [id, isEdit]);

  const handleChange = (e) => {
    const val = e.target.type === 'checkbox' ? (e.target.checked ? 1 : 0) : e.target.value;
    setForm({ ...form, [e.target.name]: val });
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    try {
      if (isEdit) {
        await API.put(`/news/${id}`, form);
      } else {
        await API.post('/news', form);
      }
      navigate('/news');
    } catch (err) {
      setError(err.response?.data?.message || 'Save failed.');
    } finally {
      setSaving(false);
    }
  };

  const uploadImage = async (file) => {
    if (!isEdit) return alert('Save the article first, then upload images.');
    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    fd.append('description', imgDesc);
    try {
      const { data } = await API.post(`/news/${id}/images`, fd);
      setImages((imgs) => [...imgs, data]);
      setImgDesc('');
    } catch (err) {
      alert(err.response?.data?.message || 'Upload failed.');
    } finally {
      setUploading(false);
    }
  };

  const deleteImage = async (imgId) => {
    if (!window.confirm('Delete this image?')) return;
    await API.delete(`/news/${id}/images/${imgId}`);
    setImages((imgs) => imgs.filter((x) => x.id !== imgId));
  };

  const categories = ['General', 'Technology', 'Investment', 'Business', 'Economy', 'Health', 'Education'];

  return (
    <div style={{ maxWidth: 800 }}>
      <h1 style={{ fontSize: 24, marginBottom: 28 }}>{isEdit ? 'Edit Article' : 'Add News Article'}</h1>

      {error && <div style={errorBox}>{error}</div>}

      <form onSubmit={handleSave}>
        <Section title="English Content">
          <Field label="Title (English) *" name="title" value={form.title} onChange={handleChange} required />
          <Field label="Content (English) *" name="content" value={form.content} onChange={handleChange} textarea required />
        </Section>

        <Section title="Amharic Content (አማርኛ)">
          <Field label="Title (Amharic)" name="title_am" value={form.title_am} onChange={handleChange} />
          <Field label="Content (Amharic)" name="content_am" value={form.content_am} onChange={handleChange} textarea />
        </Section>

        <Section title="Oromo Content (Afaan Oromoo)">
          <Field label="Title (Oromo)" name="title_or" value={form.title_or} onChange={handleChange} />
          <Field label="Content (Oromo)" name="content_or" value={form.content_or} onChange={handleChange} textarea />
        </Section>

        <Section title="Settings">
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>
            <div>
              <label style={{ display: 'block', fontSize: 13, color: '#a3a3a3', marginBottom: 6 }}>Category</label>
              <select name="category" value={form.category} onChange={handleChange} style={inputStyle}>
                {categories.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, paddingTop: 24 }}>
              <input type="checkbox" id="published" name="is_published" checked={form.is_published === 1} onChange={handleChange} style={{ width: 18, height: 18 }} />
              <label htmlFor="published" style={{ fontSize: 14, color: '#fff' }}>Publish immediately</label>
            </div>
          </div>
        </Section>

        <button type="submit" disabled={saving} style={btnPrimary}>
          {saving ? 'Saving...' : isEdit ? 'Save Changes' : 'Create Article'}
        </button>
      </form>

      {isEdit && (
        <Section title="Images">
          <p style={{ color: '#a3a3a3', fontSize: 13, marginBottom: 12 }}>Upload images for this article.</p>
          <input
            type="text"
            placeholder="Image description (optional)"
            value={imgDesc}
            onChange={(e) => setImgDesc(e.target.value)}
            style={{ ...inputStyle, marginBottom: 12 }}
          />
          <label style={uploadBtn}>
            {uploading ? 'Uploading...' : '📸 Upload Image'}
            <input type="file" accept="image/*" hidden onChange={(e) => e.target.files[0] && uploadImage(e.target.files[0])} />
          </label>

          {images.length > 0 && (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginTop: 16 }}>
              {images.map((img) => (
                <div key={img.id} style={{ position: 'relative', borderRadius: 10, overflow: 'hidden', background: '#262626' }}>
                  <img src={img.url} alt={img.description} style={{ width: '100%', height: 130, objectFit: 'cover' }} />
                  <div style={{ padding: '6px 10px', fontSize: 12, color: '#a3a3a3' }}>{img.description || 'No description'}</div>
                  <button onClick={() => deleteImage(img.id)} style={deleteBtn}>✕</button>
                </div>
              ))}
            </div>
          )}
        </Section>
      )}
    </div>
  );
}

const Section = ({ title, children }) => (
  <div style={{ background: '#171717', border: '1px solid #262626', borderRadius: 14, padding: 24, marginBottom: 20 }}>
    <h3 style={{ fontSize: 16, marginBottom: 18, color: '#f97316' }}>{title}</h3>
    {children}
  </div>
);

const Field = ({ label, name, value, onChange, required, textarea }) => (
  <div style={{ marginBottom: 14 }}>
    <label style={{ display: 'block', fontSize: 13, color: '#a3a3a3', marginBottom: 6 }}>{label}</label>
    {textarea ? (
      <textarea name={name} value={value} onChange={onChange} required={required} rows={5} style={{ ...inputStyle, resize: 'vertical' }} />
    ) : (
      <input type="text" name={name} value={value} onChange={onChange} required={required} style={inputStyle} />
    )}
  </div>
);

const inputStyle = { width: '100%', padding: '10px 12px', background: '#0a0a0a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: 14 };
